function migrateItems(items){const current=Array.isArray(items)?items:[];const kept=current.filter(i=>!oldAutoItem(i));const ids=new Set(kept.map(i=>Number(i.id)));DEFAULT_ITEMS.forEach(i=>{if(!ids.has(i.id))kept.push(clone(i))});kept.forEach(i=>{const legacy={Arma:'Armas',Missão:'Itens Chave',Consumível:'Consumíveis',Material:'Materiais',Relíquia:'Relíquias',Mágico:'Relíquias',Armadura:'Diversos',Comum:'Diversos'};if(legacy[i.category])i.category=legacy[i.category];i.weight=inferWeight(i);i.maxQty=Math.max(1,Number(i.maxQty)||10);if(i.id===300){i.name='Chave';i.category='Itens Chave';i.icon='asset:key';i.weight=1}});return kept}

