 root.innerHTML=`<div class="angel-aura"></div><img class="angel-art" src="anjo-profecia.jpg" alt=""><div class="angel-eye-pupil"></div><div class="angel-morse" hidden></div>`;
 document.body.appendChild(root);angelRoot=root;angelPupil=root.querySelector('.angel-eye-pupil');angelMorseBox=root.querySelector('.angel-morse');
