    document.getElementById('spotifyPlayGlobal')?.addEventListener('click',spotifyPlayCurrent);document.getElementById('spotifyPauseGlobal')?.addEventListener('click',spotifyPause);document.getElementById('spotifyLogoutGlobal')?.addEventListener('click',()=>{spotifyLogout();syncGlobalMusic()});document.getElementById('spotifyLoginGlobal')?.addEventListener('click',async()=>{const id=document.getElementById('spotifyClientIdGlobal')?.value.trim()||spotifyClientId();if(!id){toast('Informe o Client ID do Spotify.');return}localSet(SPOTIFY_CLIENT_KEY,id);await spotifyLogin()});
