function bindNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>render(b.dataset.nav));const l=document.getElementById('logout');if(l)l.onclick=()=>{state.session=null;save();render()}}
function playerThemesMarkup(p){const themes=Array.isArray(p.musicThemes)?p.musicThemes:[];return `<article class="sheet-card character-themes"><div class="section-heading"><div><span class="section-kicker">TRILHAS DO PERSONAGEM</span><h2>A música que acompanha sua história</h2></div></div><p class="muted small">Crie trilhas separadas, como Música de Morte, Tema de Combate ou Tema Pessoal. Você escolhe o título e o link.</p><div class="theme-add-grid"><input id="themeLabel" placeholder="Ex.: Música de morte"><input id="themeTitle" placeholder="Ex.: Old Doll"><input id="themeUrl" placeholder="Link do Spotify ou URL da música"><button class="btn gold" id="addTheme">Adicionar trilha</button></div><div class="character-theme-list">${themes.length?themes.map((t,i)=>`<div class="character-theme-card"><div><span class="theme-label">${esc(t.label||'TRILHA')}</span><h3>${esc(t.title||'Sem título')}</h3><small>${esc(t.url||'')}</small></div><div class="row"><a class="btn small" href="${esc(t.url||'#')}" target="_blank" rel="noopener">Abrir</a><button class="btn small danger" data-remove-theme="${i}">Remover</button></div></div>`).join(''):'<div class="empty">Nenhuma trilha cadastrada para este personagem.</div>'}</div></article>`}
function playerWallpaperMarkup(p){return `<article class="sheet-card character-wallpaper"><div class="section-heading"><div><span class="section-kicker">WALLPAPER PESSOAL</span><h2>Fundo do seu personagem</h2></div></div><p class="muted small">Escolha uma imagem para personalizar o início do seu próprio registro.</p><div class="wallpaper-preview" id="playerWallpaperPreview" style="${p.homeWallpaper?`background-image:linear-gradient(90deg,rgba(0,0,0,.5),rgba(0,0,0,.15)),url('${esc(p.homeWallpaper)}')`:''}"></div><label class="upload-label">Alterar wallpaper<input id="playerWallpaperInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></label>${p.homeWallpaper?'<button class="btn small danger" id="clearPlayerWallpaper">Remover wallpaper</button>':''}</article>`}
function bindSheet(){const p=player();if(!p)return;syncDerivedResources(p);const saveId=document.getElementById('saveIdentity');const cls=document.getElementById('pClass');if(cls)cls.onchange=()=>{if(classChosen(p)){toast('A classe já está selada.');render('sheet');return}if(!cls.value)return;if(!confirm(`Escolher ${cls.value}?\n\nEsta escolha é definitiva para este personagem.`)){render('sheet');return}p.class=cls.value;p.initialSpell='';save();toast('Seu destino está selado.');render('sheet')};if(saveId)saveId.onclick=()=>{p.name=document.getElementById('pName').value.trim()||p.name;if(!classChosen(p)&&document.getElementById('pClass'))p.class=document.getElementById('pClass').value;p.extra=Math.max(0,Number(document.getElementById('extra')?.value)||p.extra||0);p.soul=document.getElementById('soul').value.trim();p.belovedObjects=document.getElementById('belovedObjects').value.trim();p.personality=document.getElementById('personality').value.trim();p.destiny=document.getElementById('destiny').value.trim();p.description=document.getElementById('description').value.trim();p.history=document.getElementById('history').value.trim();p.attrs.Corpo=clamp(p.attrs.Corpo,0,MAX_ATTR);p.attrs.Sanidade=clamp(p.attrs.Sanidade,0,MAX_ATTR);syncDerivedResources(p);p.hp=clamp(document.getElementById('hp').value,0,p.hpMax);p.sanity=clamp(document.getElementById('sanity').value,0,p.sanityMax);p.attack=Number(document.getElementById('attack').value)||0;p.defense=Number(document.getElementById('defense').value)||0;save();toast('Ficha atualizada.');render('sheet')};const history=document.getElementById('saveHistory');if(history)history.onclick=()=>{p.description=document.getElementById('description').value;p.history=document.getElementById('history').value;save();toast('Descrição e história salvas.');render('sheet')};const photo=document.getElementById('photoInput');if(photo)photo.onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast('Imagem inválida ou maior que 5 MB.');return}imageFileToDataURL(f,900,.8).then(data=>{p.photo=data;save();document.getElementById('charPhoto').src=data;toast('Imagem salva.')}).catch(()=>toast('Não foi possível processar a imagem.'))};const soulPhoto=document.getElementById('soulPhotoInput');if(soulPhoto)soulPhoto.onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast('Imagem inválida ou maior que 5 MB.');return}imageFileToDataURL(f,700,.8).then(data=>{p.soulPhoto=data;save();document.getElementById('soulPhoto').src=data;toast('Imagem da alma salva.')}).catch(()=>toast('Não foi possível processar a imagem.'))};const sa=document.getElementById('saveAttrs');if(sa)sa.onclick=()=>{document.querySelectorAll('.pAttr').forEach(x=>p.attrs[x.dataset.attr]=clamp(x.value,0,MAX_ATTR));syncDerivedResources(p);save();toast('Atributos salvos. Máximo 8.');render('sheet')};const ss=document.getElementById('saveSkills');if(ss)ss.onclick=()=>{document.querySelectorAll('.pSkill').forEach(x=>p.skills[x.dataset.skill]=clamp(x.value,0,MAX_SKILL));save();toast('Perícias salvas. Máximo 15.');render('sheet')};const wp=document.getElementById('playerWallpaperInput');if(wp)wp.onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast('Wallpaper inválido ou maior que 5 MB.');return}imageFileToDataURL(f,1400,.82).then(data=>{p.homeWallpaper=data;save();toast('Wallpaper do personagem salvo.');render('sheet')}).catch(()=>toast('Não foi possível processar o wallpaper.'))};const cwp=document.getElementById('clearPlayerWallpaper');if(cwp)cwp.onclick=()=>{p.homeWallpaper='';save();toast('Wallpaper removido.');render('sheet')};const addTheme=document.getElementById('addTheme');if(addTheme)addTheme.onclick=()=>{const label=document.getElementById('themeLabel')?.value.trim(),title=document.getElementById('themeTitle')?.value.trim(),url=document.getElementById('themeUrl')?.value.trim();if(!label||!title||!url){toast('Preencha tipo, nome e link da trilha.');return}p.musicThemes=p.musicThemes||[];p.musicThemes.push({label,title,url});save();toast('Trilha do personagem adicionada.');render('sheet')};document.querySelectorAll('[data-remove-theme]').forEach(b=>b.onclick=()=>{p.musicThemes.splice(Number(b.dataset.removeTheme),1);save();toast('Trilha removida.');render('sheet')});const roll=document.getElementById('rollD20');if(roll)roll.onclick=()=>{const d=document.getElementById('d20Display');if(d){d.classList.remove('throw');void d.offsetWidth;d.classList.add('throw')}rollD20For(p,'Teste 1d20')};document.querySelectorAll('[data-spell-choice]').forEach(b=>b.onclick=()=>{if(!hasMagicClass(p.class)||p.initialSpell)return;const sp=getSpells().find(x=>x.id===b.dataset.spellChoice);if(!sp)return;if(!confirm(`Escolher ${sp.name}?\n\nVocê só poderá escolher uma magia inicial.`))return;p.initialSpell=b.dataset.spellChoice;save();toast('Magia inicial escolhida.');render('sheet')});document.querySelectorAll('[data-remove-slot]').forEach(b=>b.onclick=()=>{p.backpack.splice(Number(b.dataset.removeSlot),1);save();render('sheet')});const add=document.getElementById('addBagItem');if(add)add.onclick=()=>addBag(p)}

function home(){
 const master=state.session.role==='master',p=player();
 if(master)return shell(`<section class="home-book"><div class="home-book-copy"><span class="badge">A PROFECIA</span><h1>O livro foi aberto.</h1><p>A Câmara do Mestre aguarda. Controle Players, Monstros, condições, itens, sons, fundos e a trilha global sem apagar o que já existe.</p><div class="home-actions"><button class="btn primary" data-nav="master">Abrir Câmara do Mestre</button><button class="btn gold" data-nav="classes">Ver Classes</button></div></div><div class="home-seal"><div class="home-seal-inner">✦<span>SEU<br>DESTINO</span></div></div></section><section class="home-panels"><article class="home-panel featured"><span class="section-kicker">REGISTRO</span><h2>Os nomes permanecem.</h2><p>Players e Monstros criados pelo Mestre ficam registrados até serem excluídos.</p></article><article class="home-panel"><span class="section-kicker">TRILHA</span><h2>${state.music?.title?esc(state.music.title):'Nenhuma trilha'}</h2><p>Spotify e arquivos locais continuam separados.</p></article>${spotifyHomePanel()}</section>`,'home');
 syncDerivedResources(p);
 const trained=[...new Set(SKILLS.filter(sk=>(effectiveSkill(p,sk)||0)>0))];
 const wallpaper=p?.homeWallpaper?` style="--player-wallpaper:url('${esc(p.homeWallpaper)}')"`:'';const themes=Array.isArray(p?.musicThemes)?p.musicThemes:[];return shell(`<section class="op-home-sheet player-personalized"${wallpaper}><div class="op-topline"><div><span class="badge">PERSONAGEM</span><h1>${esc(p?.name||'Player')}</h1><p>${esc(p?.class||'Classe não escolhida')} • ${esc(p?.status||'Ativo')}</p></div><div class="op-resource-strip"><div><span>VIDA</span><b>${p?.hp||0}/${p?.hpMax||0}</b></div><div><span>SANIDADE</span><b>${p?.sanity||0}/${p?.sanityMax||0}</b></div></div></div><div class="op-dossier-grid"><section class="op-attributes"><div class="section-heading"><div><span class="section-kicker">ATRIBUTOS</span><h2>Estado atual</h2></div><span class="corner-mark">SOMENTE LEITURA</span></div><div class="op-attr-list">${ATTRS.map(a=>`<div class="op-attr-row"><span class="op-attr-symbol">${uiAttrIcon(a)}</span><span>${esc(a)}</span><b>${effectiveAttr(p,a)}</b></div>`).join('')}</div></section><section class="op-trained"><div class="section-heading"><div><span class="section-kicker">PERÍCIAS</span><h2>Treinadas</h2></div><span class="corner-mark">${trained.length}</span></div><div class="op-trained-list">${trained.length?trained.map(sk=>`<div class="op-skill-row"><span>${uiSkillIcon(sk)} ${esc(sk)}</span><b>${effectiveSkill(p,sk)}</b></div>`).join(''):'<div class="empty">Nenhuma perícia treinada.</div>'}</div></section><aside class="op-profile"><div class="op-portrait-frame"><img src="${esc(p?.photo||'ritual.jpg')}" alt="Retrato do personagem"><span class="portrait-mark">✦</span></div><div><span class="section-kicker">REGISTRO</span><h2>${esc(p?.class||'Sem classe')}</h2><p>Ficha inicial inspirada em uma folha de personagem: leitura rápida, atributos totais e apenas perícias treinadas.</p></div></aside></div><div class="op-home-actions"><button class="btn primary" data-nav="sheet">Abrir ficha completa</button><button class="btn gold" data-nav="classes">${classChosen(p)?'Consultar Classes':'Escolher Classe'}</button></div></section><section class="home-player-themes"><div class="section-heading"><div><span class="section-kicker">TRILHAS PESSOAIS</span><h2>O som deste personagem</h2></div></div><div class="home-theme-grid">${themes.length?themes.map(t=>`<a class="home-theme-card" href="${esc(t.url)}" target="_blank" rel="noopener"><span>${esc(t.label)}</span><strong>${esc(t.title)}</strong><small>Abrir trilha ↗</small></a>`).join(''):'<div class="empty">Este personagem ainda não registrou suas trilhas.</div>'}</div></section>${spotifyHomePanel()}`,'home')}

function classesPage(){const p=player();const chosen=classChosen(p);return shell(`<section class="classes-hero"><div class="classes-hero-copy"><span class="badge">CAMINHOS</span><h1>Classes</h1><p>${chosen?'Seu caminho já foi escolhido. O destino não pode ser alterado depois da confirmação.':'Escolha com cuidado. A classe pode ser escolhida apenas uma vez e os bônus serão gravados na ficha.'}</p><div class="destiny-phrase ${chosen?'show':''}" id="destinyPhrase">${chosen?'Seu destino está selado':'Seu destino aguarda'}</div></div></section><div class="class-book-grid">${Object.entries(CLASSES).map(([n,c])=>`<article class="class-book-card ${chosen&&p.class===n?'chosen-class':''} ${chosen&&p.class!==n?'locked-class':''}" data-class-choice="${esc(n)}"><div class="class-card-ornament">${chosen&&p.class===n?'✦':'◇'}</div><div class="class-card-head"><h2>${esc(n)}</h2>${hasMagicClass(n)?'<span class="badge">MAGIA / RITUAL</span>':''}</div><p>${esc(c.desc)}</p><div class="class-bonus-line"><strong>Bônus</strong><span>${esc(c.bonus)}</span></div><div class="ability-list">${c.abilities.map(a=>`<div class="ability"><b>${esc(a[0])}</b><div class="small muted">${esc(a[1])}</div></div>`).join('')}</div>${chosen&&p.class===n?'<div class="class-choice-seal">CLASSE ESCOLHIDA</div>':''}</article>`).join('')}</div>`,`classes`)}
function hpFields(e,editable=true){const dis=editable?'':'disabled';const hpMax=derivedMax(e,'Corpo')||1;const sanityMax=derivedMax(e,'Sanidade');const hp=clamp(e.hp??hpMax,0,hpMax);const sanity=clamp(e.sanity??sanityMax,0,sanityMax);return `<div class="input-grid resource-grid"><div class="resource-box hp"><span>VIDA</span><strong>${hp}/${hpMax}</strong><div class="field"><input id="hp" type="number" min="0" max="35" value="${hp}" ${dis}></div></div><div class="resource-box sanity-resource"><span>SANIDADE</span><strong>${sanity}/${sanityMax}</strong><div class="field"><input id="sanity" type="number" min="0" max="35" value="${sanity}" ${dis}></div></div><div class="resource-box"><span>ATAQUE</span><strong>${e.attack}</strong><div class="field"><input id="attack" type="number" value="${e.attack}" ${dis}></div></div><div class="resource-box"><span>DEFESA</span><strong>${e.defense}</strong><div class="field"><input id="defense" type="number" value="${e.defense}" ${dis}></div></div></div><p class="resource-rule">Os limites são calculados automaticamente a partir dos atributos Corpo e Sanidade, respeitando o máximo de 35.</p>`}
function slots(e,editable=true){const used=bagWeight(e);return `<div class="row space"><div><h3>Mochila</h3><span class="small ${used>MAX_BAG?'danger-text':'muted'}">${used}/${MAX_BAG} espaços usados • peso por unidade: 1–3</span></div>${editable?'<button class="btn small" id="addBagItem">Adicionar item</button>':'<span class="small muted">Somente o Mestre pode alterar</span>'}</div><div class="slot-grid" style="margin-top:12px">${Array.from({length:MAX_BAG},(_,i)=>{const b=e.backpack[i],it=b&&item(b.id);return `<div class="slot ${it?'filled':''}">${it?`${editable?`<button data-remove-slot="${i}">×</button>`:''}<div class="slot-icon">${itemIcon(it)}</div><div class="slot-name">${esc(it.name)}</div><div class="slot-id">ID ${String(it.id).padStart(3,'0')} • Peso ${inferWeight(it)}</div><div class="slot-qty">Qtd. ${b.qty} • ${inferWeight(it)*b.qty} espaço${inferWeight(it)*b.qty===1?'':'s'}</div>`:'<div class="slot-icon" style="opacity:.15">◇</div><div class="small muted">Espaço vazio</div>'}</div>`}).join('')}</div>`}
function spellMarkup(p){if(!hasMagicClass(p.class))return '';const spells=getSpells(),selected=spells.find(x=>x.id===p.initialSpell);if(selected)return `<article class="sheet-card spell-card selected-spell"><div class="section-heading"><div><span class="section-kicker">MAGIA INICIAL</span><h2>${esc(selected.name)}</h2></div><span class="dice-type">${esc(selected.cost)}</span></div>${selected.image?`<img class="spell-image" src="${esc(selected.image)}" alt="">`:''}<p class="spell-school">${esc(selected.school)}</p><p>${esc(selected.description)}</p><div class="row"><span class="badge">ESCOLHIDA</span></div></article>`;return `<article class="sheet-card spell-card"><div class="section-heading"><div><span class="section-kicker">MAGIAS INICIAIS</span><h2>Escolha apenas uma</h2></div><span class="corner-mark">1 escolha</span></div><p class="muted small">As demais desaparecem assim que você escolher uma. As imagens são definidas pelo Mestre.</p><div class="spell-grid">${spells.map(sp=>`<button type="button" class="spell-option" data-spell-choice="${esc(sp.id)}">${sp.image?`<img src="${esc(sp.image)}" alt="">`:`<span class="spell-placeholder">✦</span>`}<strong>${esc(sp.name)}</strong><small>${esc(sp.school)}</small><span>${esc(sp.cost)}</span></button>`).join('')}</div></article>`}
function sheet(){const p=player();if(!p)return shell('<div class="empty">Player não encontrado.</div>','sheet');syncDerivedResources(p);const last=p.rolls?.[p.rolls.length-1];const hpMax=derivedMax(p,'Corpo')||1;const sanityMax=derivedMax(p,'Sanidade');const bonus=classBonusMap(p.class);const chosen=classChosen(p);const currentClass=CLASSES[p.class]||{desc:'Escolha uma classe para revelar suas habilidades e bônus.',bonus:'—',abilities:[]};return shell(`<section class="profile-header"><div><span class="badge">PLAYER</span><h1>${esc(p.name)}</h1><p>${esc(p.class||'Classe não escolhida')} <span class="sep">•</span> ${esc(p.status)}</p><div class="destiny-phrase" id="destinyPhrase">Seu destino está selado</div></div><div class="profile-seal"><img src="runa-gold.png" alt=""></div></section><div class="sheet-layout"><section class="sheet-main"><article class="sheet-card character-card"><div class="character-portrait"><img class="photo" id="charPhoto" src="${p.photo||'ritual.jpg'}" alt="Retrato"><label class="upload-label">Alterar retrato<input id="photoInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></div><div class="character-info"><div class="eyebrow">IDENTIDADE</div><div class="field-inline"><label>Nome</label><input id="pName" value="${esc(p.name)}"></div><div class="field-inline"><label>Classe</label><div class="class-lock-field">${chosen?`<strong>${esc(p.class)}</strong><span>Escolha já selada</span>`:`<select id="pClass"><option value="">Escolha sua classe</option>${Object.keys(CLASSES).map(c=>`<option ${p.class===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`}</div></div><div class="small-stat-row"><div><span>PONTOS EXTRAS</span><strong>${p.extra||0}</strong></div><div><span>VIDA MÁX.</span><strong>${hpMax}</strong></div><div><span>SANIDADE MÁX.</span><strong>${sanityMax}</strong></div></div><div class="class-bonus-summary"><span>BÔNUS DA CLASSE</span><strong>${esc(classBonusText(p.class))}</strong></div><button class="btn primary" id="saveIdentity">Salvar ficha</button></div></article>${playerThemesMarkup(p)}${playerWallpaperMarkup(p)}<article class="sheet-card resources-card"><div class="section-heading"><div><span class="section-kicker">RECURSOS</span><h2>Estado do corpo e da mente</h2></div></div>${hpFields(p,true)}</article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">ATRIBUTOS</span><h2>Até 8 pontos por atributo</h2></div><span class="corner-mark">máx. 8</span></div><div class="attribute-grid">${ATTRS.map(a=>{const b=bonus[a]||0;return `<label class="attribute-box"><span class="attr-icon">${uiAttrIcon(a)}</span><span class="attr-name">${esc(a)}</span><input class="pAttr" data-attr="${esc(a)}" type="number" min="0" max="8" value="${p.attrs[a]}" ><span class="attr-cap">/ 8</span>${b?`<small class="attr-bonus">+${b} classe • efetivo ${effectiveAttr(p,a)}</small>`:''}</label>`}).join('')}</div><p class="resource-rule">Corpo e Sanidade determinam automaticamente os limites de Vida e Sanidade. Máximo de 35.</p><button class="btn primary" id="saveAttrs">Salvar atributos</button></article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">PERÍCIAS</span><h2>Até 15 pontos por perícia</h2></div><span class="corner-mark">máx. 15</span></div><div class="skills-groups">${Object.entries(SKILL_GROUPS).map(([g,items])=>`<div class="skill-group"><div class="skill-group-title">${esc(g)}</div>${items.map(sk=>`<label class="skill-line"><span class="skill-name"><i class="skill-icon">${uiSkillIcon(sk)}</i><span>${esc(sk)}${classBonusMap(p.class)[sk]?`<small class="skill-bonus">+${classBonusMap(p.class)[sk]} classe • efetivo ${effectiveSkill(p,sk)}</small>`:''}</span></span><input class="pSkill" data-skill="${esc(sk)}" type="number" min="0" max="15" value="${p.skills[sk]||0}"><b>/15</b></label>`).join('')}</div>`).join('')}</div><button class="btn primary" id="saveSkills">Salvar perícias</button></article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">ROLAGEM</span><h2>Rolagem de dados</h2></div><span class="dice-type">1d20</span></div><div class="dice-panel"><div class="d20-display ${last?'has-result':''}" id="d20Display"><span class="d20-face">${last?last.value:'20'}</span><small>1d20</small></div><div class="dice-actions"><button class="btn dice-btn" id="rollD20">Rolar 1d20</button><p class="muted small">Role diretamente na ficha. O resultado fica registrado.</p></div></div><div class="roll-history">${(p.rolls||[]).slice().reverse().slice(0,8).map(r=>`<div class="roll-entry"><strong>${r.value}</strong><span>${esc(r.label)}</span><time>${esc(r.time)}</time></div>`).join('')||'<div class="empty">Nenhuma rolagem ainda.</div>'}</div></article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">ESTADOS</span><h2>Condições atuais</h2></div></div><div class="condition-legend">Condições aplicadas pelo Mestre aparecem aqui.</div>${conditionsMarkup(p)}</article>${spellMarkup(p)}<article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">ALMA</span><h2>O que permanece</h2></div></div><div class="soul-layout"><div class="photo-wrap"><img class="photo soul-photo" id="soulPhoto" src="${p.soulPhoto||'runa-gold.png'}" alt="Alma"><label class="upload-label">Imagem da alma<input id="soulPhotoInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></div><div class="text-fields"><div class="field"><label>Sua alma</label><input id="soul" value="${esc(p.soul)}"></div><div class="field"><label>Objetos queridos</label><textarea id="belovedObjects" rows="4">${esc(p.belovedObjects)}</textarea></div></div></div><div class="story-grid"><div class="field"><label>Personalidade</label><textarea id="personality" rows="5">${esc(p.personality)}</textarea></div><div class="field"><label>Destino</label><textarea id="destiny" rows="5">${esc(p.destiny)}</textarea></div></div></article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">DESCRIÇÃO & HISTÓRIA</span><h2>Sua história</h2></div></div><div class="story-grid"><div class="field"><label>Descrição</label><textarea id="description" rows="6" placeholder="Aparência, presença, voz e detalhes que definem este personagem.">${esc(p.description||'')}</textarea></div><div class="field"><label>História</label><textarea id="history" rows="6" placeholder="Escreva aqui a história, feitos, perdas e marcas que definem este personagem.">${esc(p.history||'')}</textarea></div></div><button class="btn primary" id="saveHistory">Salvar descrição e história</button></article><article class="sheet-card"><div class="section-heading"><div><span class="section-kicker">MOCHILA</span><h2>10 espaços • peso dinâmico</h2></div></div>${slots(p,true)}</article></section><aside class="sheet-side"><article class="sheet-card sticky-card"><div class="section-heading"><div><span class="section-kicker">CLASSE ATUAL</span><h2>${esc(p.class)}</h2></div></div><p class="muted">${esc(currentClass.desc)}</p><div class="class-bonus-summary"><span>BÔNUS</span><strong>${esc(currentClass.bonus)}</strong></div><div class="ability-list">${currentClass.abilities.map(a=>`<div class="ability"><b>${esc(a[0])}</b><div class="small muted">${esc(a[1])}</div></div>`).join('')}</div></article><article class="sheet-card sticky-card"><div class="section-heading"><div><span class="section-kicker">RESUMO</span><h2>Estado atual</h2></div></div><div class="active-conditions">${(p.conditions||[]).map(id=>{const c=CONDITION_DEFS.find(x=>x.id===id);const img=state.uiIcons?.conditions?.[c?.id]||c?.image;return c?`<div class="active-condition">${img?`<img src="${esc(img)}" alt="">`:`<span>${esc(c.icon)}</span>`}<div><b>${esc(c.name)}</b><small>${esc(conditionEffectText(c.id,p))}</small></div></div>`:''}).join('')||'<div class="empty">Nenhuma condição ativa.</div>'}</div></article></aside></div>`,'sheet')}

function soundsAdmin(){return `<div class="card"><div class="row space"><div><h2>Música e Sons</h2><p class="small muted">A Caixa de Sons continua exclusiva do Mestre. Arquivos locais ficam no IndexedDB deste navegador; URLs são mantidas como atalhos.</p></div></div><div class="music-sound-grid"><section class="music-admin-section"><div class="section-kicker">CAIXA DE SONS</div><h3>Adicionar efeito</h3><div class="input-grid"><div class="field"><label>Nome</label><input id="soundName" placeholder="Ex.: Porta, trovão, grito..."></div><div class="field"><label>Arquivo de áudio</label><input id="soundFile" type="file" accept="audio/*"></div></div><div class="field"><label>Ou URL de áudio</label><input id="soundUrl" placeholder="https://.../som.mp3"></div><button class="btn primary" id="addSound">+ Adicionar som</button><div class="sound-list-admin">${state.sounds?.length?state.sounds.map(s=>`<div class="sound-admin-row"><div><strong>${esc(s.name)}</strong><small>${s.kind==='file'?'Arquivo local':'URL externa'}</small></div><div class="row"><button class="btn small" data-play-sound="${esc(s.id)}">▶ Testar</button><button class="btn small danger" data-del-sound="${esc(s.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum som cadastrado.</div>'}</div></section><section class="music-admin-section"><div class="section-kicker">SPOTIFY</div><h3>Conexão do Mestre</h3><p class="small muted">Use OAuth 2.0 com PKCE. O Client ID não é segredo; tokens ficam separados por usuário e não são gravados no código.</p><div class="field"><label>Client ID</label><input id="spotifyClientId" value="${esc(spotifyClientId())}" placeholder="Client ID do Spotify for Developers"></div><div class="field"><label>Redirect URI exata</label><input value="${esc(spotifyRedirectUri())}" readonly></div><div class="row"><button class="btn gold" id="spotifyLogin">${spotifyLogged()?'Spotify conectado':'Entrar com Spotify'}</button>${spotifyLogged()?'<button class="btn" id="spotifyLogout">Desconectar</button>':''}</div><div class="spotify-admin-note">${spotifyLogged()?'Sua conta está conectada neste navegador.':'Conecte sua conta para reproduzir a trilha completa no navegador. Para Web Playback, o Spotify exige Premium.'}</div></section></div></div>`}

function symbolsAdmin(){return `<div class="card"><div class="row space"><div><h2>Símbolos da ficha</h2><p class="small muted">Somente o Mestre pode alterar os símbolos de atributos, perícias e condições. Você pode usar texto/emoji ou enviar uma imagem; imagens pequenas são otimizadas antes de salvar.</p></div></div><div class="symbol-editor"><div><h3>Atributos</h3>${ATTRS.map(a=>`<div class="symbol-row"><span>${uiAttrIcon(a)} ${esc(a)}</span><div class="symbol-controls"><input class="uiAttrIconInput" data-symbol-attr="${esc(a)}" value="${esc(state.uiIcons?.attrs?.[a]||DEFAULT_ATTR_ICONS[a])}"><label class="btn small">Imagem<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-symbol-file="attr" data-symbol-key="${esc(a)}" hidden></label></div></div>`).join('')}</div><div><h3>Perícias</h3>${SKILLS.map(sk=>`<div class="symbol-row"><span>${uiSkillIcon(sk)} ${esc(sk)}</span><div class="symbol-controls"><input class="uiSkillIconInput" data-symbol-skill="${esc(sk)}" value="${esc(state.uiIcons?.skills?.[sk]||DEFAULT_SKILL_ICONS[sk])}"><label class="btn small">Imagem<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-symbol-file="skill" data-symbol-key="${esc(sk)}" hidden></label></div></div>`).join('')}</div></div><div class="divider"></div><h3>Ícones das condições</h3><div class="condition-upload-admin">${CONDITION_DEFS.map(c=>{const img=state.uiIcons?.conditions?.[c.id]||c.image;return `<div class="condition-admin-row"><div>${img?`<img class="condition-admin-icon" src="${esc(img)}" alt="">`:''}<strong>${esc(c.name)}</strong></div><label class="btn small">Alterar<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-condition-image="${c.id}" hidden></label></div>`}).join('')}</div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="saveSymbols">Salvar símbolos de texto</button></div></div>`}
function spellsAdmin(){return `<div class="card"><div class="row space"><div><h2>Magias iniciais</h2><p class="small muted">O Mestre controla as imagens. Os Players só podem escolher uma magia inicial quando a classe permitir.</p></div></div><div class="spell-admin-grid">${getSpells().map(sp=>`<div class="spell-admin-card">${sp.image?`<img class="spell-image" src="${esc(sp.image)}" alt="">`:'<div class="spell-upload-placeholder">✦</div>'}<strong>${esc(sp.name)}</strong><small>${esc(sp.school)} • ${esc(sp.cost)}</small><label class="upload-label">Enviar imagem<input type="file" accept="image/png,image/jpeg,image/webp" data-spell-image="${esc(sp.id)}" hidden></label>${sp.image?'<button class="btn small danger" data-clear-spell-image="'+esc(sp.id)+'">Remover imagem</button>':''}</div>`).join('')}</div></div>`}

function masterFicha(){return shell(`<section class="hero"><span class="badge">FICHAS</span><h1>Fichas dos Players</h1><p>Os Players criados pelo Mestre ficam reunidos aqui. Abra uma ficha para consultar seus dados ou edite pelo botão de edição.</p></section><div class="master-player-grid">${state.players.map((p,i)=>`<article class="master-player-card"><div class="master-player-avatar"><img src="${esc(p.photo||'ritual.jpg')}" alt=""></div><div class="master-player-info"><span class="section-kicker">PLAYER</span><h2>${esc(p.name||'Sem nome')}</h2><p>${esc(p.class||'Classe não escolhida')} • ${esc(p.status||'Ativo')}</p><div class="master-player-stats"><span>VIDA <b>${p.hp||0}/${derivedMax(p,'Corpo')||1}</b></span><span>SANIDADE <b>${p.sanity||0}/${derivedMax(p,'Sanidade')}</b></span><span>MOCHILA <b>${bagWeight(p)}/${MAX_BAG}</b></span></div><div class="row"><button class="btn small" data-view-player="${i}">Abrir ficha</button><button class="btn small" data-edit-p="${i}">Editar</button><button class="btn small" data-bag-p="${i}">Mochila</button><button class="btn small danger" data-del-p="${i}">Excluir</button></div></div></article>`).join('')||'<div class="empty">Nenhum Player cadastrado.</div>'}</div><div class="master-ficha-note"><strong>Persistência</strong><span>Os registros permanecem salvos neste ambiente até o Mestre excluí-los.</span></div>`,`sheet`)}
function admin(){return shell(`<section class="hero"><span class="badge">MESTRE</span><h1>Câmara do Mestre</h1><p>Gerenciamento completo de Players, Monstros, classes, itens e trilha.</p></section><div class="panel-tabs"><button class="active" data-tab="players">Players</button><button data-tab="monsters">Monstros</button><button data-tab="classes">Classes</button><button data-tab="items">Banco de Itens</button><button data-tab="music">Trilha global</button><button data-tab="sounds">Sons</button><button data-tab="symbols">Símbolos</button><button data-tab="spells">Magias</button><button data-tab="backgrounds">Fundos</button></div><div id="adminContent">${playersAdmin()}</div>`,'master')}
function playersAdmin(){return `<div class="card"><div class="row space"><div><h2>Players</h2><p class="small muted">Criar, editar, excluir e controlar fichas.</p></div><button class="btn primary" id="newPlayer">+ Criar Player</button></div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Nome</th><th>Login</th><th>Classe</th><th>Vida</th><th>Ataque</th><th>Defesa</th><th>Mochila</th><th>Ações</th></tr></thead><tbody>${state.players.map((p,i)=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.login)}</td><td>${esc(p.class)}</td><td>${p.hp}/${p.hpMax}</td><td>${p.attack}</td><td>${p.defense}</td><td>${bagWeight(p)}/${MAX_BAG}</td><td><button class="btn small" data-edit-p="${i}">Editar</button> <button class="btn small" data-bag-p="${i}">Mochila</button> <button class="btn small" data-round-p="${i}">+ Rodada</button> <button class="btn small danger" data-del-p="${i}">Excluir</button></td></tr>`).join('')}</tbody></table></div></div>`}

function bagAdminModal(index){const p=state.players[index],used=bagWeight(p);return `<div class="modal" id="bagModal"><div class="modal-card"><button class="modal-close" id="closeBag">×</button><h2>Mochila de ${esc(p.name)}</h2><p class="small ${used>MAX_BAG?'danger-text':'muted'}">${used}/${MAX_BAG} espaços usados. O peso é por unidade e varia de 1 a 3.</p><div class="searchbar"><div class="field"><label>ID ou nome do item</label><input id="bagSearch" placeholder="Ex.: 300 ou Chave"></div><div class="field"><label>Quantidade</label><input id="bagQty" type="number" min="1" value="1"></div><button class="btn primary" id="bagAddAdmin">Adicionar</button></div><div class="slot-grid" style="margin-top:14px">${Array.from({length:MAX_BAG},(_,i)=>{const b=p.backpack[i],it=b&&item(b.id);return `<div class="slot ${it?'filled':''}">${it?`<button data-bag-remove-admin="${i}">×</button><div class="slot-icon">${itemIcon(it)}</div><div class="slot-name">${esc(it.name)}</div><div class="slot-id">ID ${String(it.id).padStart(3,'0')} • Peso ${inferWeight(it)}</div><div class="slot-qty">Qtd. ${b.qty} • ${inferWeight(it)*b.qty} espaço${inferWeight(it)*b.qty===1?'':'s'}</div>`:'<div class="slot-icon" style="opacity:.15">◇</div><div class="small muted">Espaço vazio</div>'}</div>`}).join('')}</div></div></div>`}
function bindBagAdmin(index){const close=()=>document.getElementById('bagModal')?.remove();document.getElementById('closeBag').onclick=close;document.getElementById('bagAddAdmin').onclick=()=>{const p=state.players[index],q=document.getElementById('bagSearch').value.trim().toLowerCase(),it=state.items.find(x=>String(x.id)===q||x.name.toLowerCase().includes(q));if(!it){toast('Item não encontrado.');return}const qty=Math.max(1,Number(document.getElementById('bagQty').value)||1),weight=inferWeight(it),used=bagWeight(p),ex=p.backpack.find(x=>x.id===it.id),current=ex?.qty||0,maxByWeight=Math.floor((MAX_BAG-(used-weight*current))/weight),add=Math.min(it.maxQty-current,qty,maxByWeight);if(add<=0){toast('Não há espaço suficiente.');return}if(ex)ex.qty=current+add;else p.backpack.push({id:it.id,qty:add});save();close();toast('Item adicionado à mochila.');openModal(bagAdminModal(index));bindBagAdmin(index)};document.querySelectorAll('[data-bag-remove-admin]').forEach(b=>b.onclick=()=>{state.players[index].backpack.splice(Number(b.dataset.bagRemoveAdmin),1);save();close();openModal(bagAdminModal(index));bindBagAdmin(index)})}
function monstersAdmin(){return `<div class="card"><div class="row space"><div><h2>Monstros</h2><p class="small muted">Fichas com vida limitada a 35 e limites de atributos configuráveis.</p></div><button class="btn primary" id="newMonster">+ Criar Monstro</button></div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Nome</th><th>Vida</th><th>Ataque</th><th>Defesa</th><th>Status</th><th>Ações</th></tr></thead><tbody>${state.creatures.map((m,i)=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${m.hp}/${m.hpMax}</td><td>${m.attack}</td><td>${m.defense}</td><td>${esc(m.status)}</td><td><button class="btn small" data-edit-m="${i}">Editar</button> <button class="btn small" data-round-m="${i}">+ Rodada</button> <button class="btn small danger" data-del-m="${i}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Nenhum monstro cadastrado.</div></td></tr>'}</tbody></table></div></div>`}
function itemsAdmin(){return `<div class="card"><div class="row space"><div><h2>Banco de Itens</h2><p class="small muted">${state.items.length} itens • ID 300 reservado para a Chave.</p></div><button class="btn primary" id="newItem">+ Novo item</button></div><div class="searchbar" style="margin:15px 0"><div class="field"><label>ID ou nome</label><input id="itemSearch" placeholder="300 ou Chave"></div><div class="field"><label>Categoria</label><select id="itemCat"><option value="">Todas</option>${ITEM_CATS.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Raridade</label><select id="itemRar"><option value="">Todas</option><option>Comum</option><option>Raro</option><option>Épico</option><option>Lendário</option></select></div><button class="btn" id="clearItems">Limpar</button></div><div id="itemResults"></div></div>`}
function renderItems(){const q=(document.getElementById('itemSearch')?.value||'').toLowerCase().trim(),cat=document.getElementById('itemCat')?.value||'',rar=document.getElementById('itemRar')?.value||'';const found=state.items.filter(i=>(!q||String(i.id)===q||i.name.toLowerCase().includes(q))&&(!cat||i.category===cat)&&(!rar||i.rarity===rar)).slice(0,80);document.getElementById('itemResults').innerHTML=found.length?`<div class="list">${found.map(i=>`<div class="item item-card"><div class="item-icon">${itemIcon(i)}</div><div class="item-meta"><strong>${esc(i.name)}</strong><div class="line">ID ${String(i.id).padStart(3,'0')} • ${esc(i.category)} • ${esc(i.rarity)} • Máx. ${i.maxQty} • Peso ${inferWeight(i)}</div><div class="small muted">${esc(i.description)}</div></div><div class="row"><button class="btn small" data-edit-item="${i.id}">Editar</button>${i.id!==300?`<button class="btn small danger" data-del-item="${i.id}">Excluir</button>`:''}</div></div>`).join('')}</div><p class="tiny muted">Até 80 resultados exibidos. Use a pesquisa para refinar.</p>`:'<div class="empty">Nenhum item encontrado.</div>'}
function itemModal(id=null){const e=id===null?{id:'',name:'',description:'',category:'Comum',maxQty:10,icon:'✦',effects:'',rarity:'Comum'}:clone(item(id));return `<div class="modal" id="itemModal"><div class="modal-card"><button class="modal-close" id="closeItem">×</button><h2>${id===null?'Adicionar novo item':'Editar item'}</h2><div class="input-grid"><div class="field"><label>ID</label><input id="iId" type="number" value="${e.id}" ${id===300?'disabled':''}></div><div class="field"><label>Nome</label><input id="iName" value="${esc(e.name)}"></div><div class="field"><label>Categoria</label><select id="iCat">${ITEM_CATS.map(c=>`<option ${e.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Quantidade máxima</label><input id="iMax" type="number" min="1" value="${e.maxQty}"></div><div class="field"><label>Peso por unidade (1–3 espaços)</label><input id="iWeight" type="number" min="1" max="3" value="${inferWeight(e)}"></div><div class="field"><label>Ícone</label><input id="iIcon" value="${esc(e.icon)}"></div><div class="field"><label>Raridade</label><select id="iRar">${['Comum','Raro','Épico','Lendário'].map(r=>`<option ${e.rarity===r?'selected':''}>${r}</option>`).join('')}</select></div></div><div class="field"><label>Descrição</label><textarea id="iDesc" rows="3">${esc(e.description)}</textarea></div><div class="field"><label>Efeitos</label><textarea id="iEffects" rows="3">${esc(e.effects)}</textarea></div><div class="row" style="justify-content:flex-end"><button class="btn" id="cancelItem">Cancelar</button><button class="btn primary" id="saveItem">Salvar item</button></div></div></div>`}
function musicAdmin(){const m=state.music||{};const clientId=spotifyClientId();const redirect=spotifyRedirectUri();return `<div class="music-sound-grid"><section class="music-admin-section"><div class="section-kicker">TRILHA DA CAMPANHA</div><h3>Fonte da música</h3><p class="small muted">O Mestre define a trilha global. Cada usuário reproduz a música no próprio navegador; links do Spotify não são tratados como arquivos MP3.</p><div class="input-grid"><div class="field"><label>Tipo</label><select id="musicType"><option value="audio" ${m.type==='audio'?'selected':''}>Áudio</option><option value="spotify" ${m.type==='spotify'?'selected':''}>Spotify</option></select></div><div class="field"><label>Nome da trilha</label><input id="musicTitle" value="${esc(m.title||'')}" placeholder="Nome da música"></div></div><div class="field"><label>${m.type==='spotify'?'Link ou URI do Spotify':'URL direta de áudio'}</label><input id="musicUrl" value="${m.type==='spotify'||m.kind==='url'?esc(m.url||''):''}" placeholder="${m.type==='spotify'?'https://open.spotify.com/track/...':'https://.../musica.mp3'}"></div>${m.type!=='spotify'?`<div class="field"><label>Ou enviar arquivo de áudio</label><input id="musicFile" type="file" accept="audio/*"><small class="tiny muted">Até 25 MB. O arquivo é guardado no IndexedDB deste navegador.</small></div>${m.kind==='file'&&m.mediaId?`<div class="tiny muted">Arquivo local atual: ${esc(m.title||'trilha de áudio')}</div>`:''}`:''}<div class="row"><button class="btn primary" id="saveMusic">Salvar trilha global</button><button class="btn danger" id="clearMusic">Remover trilha</button>${m.type==='spotify'&&m.url?`<a class="btn ghost" href="${esc(m.url)}" target="_blank" rel="noopener">Abrir no Spotify</a>`:''}</div></section><section class="music-admin-section"><div class="section-kicker">SPOTIFY • CONTA DO MESTRE</div><h3>Conectar Spotify</h3><p class="small muted">OAuth 2.0 Authorization Code com PKCE. O Client Secret não é colocado no frontend. A reprodução completa via Web Playback SDK exige Spotify Premium.</p><div class="field"><label>Client ID</label><input id="spotifyClientId" value="${esc(clientId)}" placeholder="Client ID do Spotify for Developers"></div><div class="field"><label>Redirect URI exata</label><input value="${esc(redirect)}" readonly></div><div class="row"><button class="btn gold" id="spotifyLogin">${spotifyLogged()?'Spotify conectado':'Entrar com Spotify'}</button>${spotifyLogged()?'<button class="btn" id="spotifyLogout">Desconectar</button>':''}</div><div class="spotify-admin-note">${spotifyLogged()?'Conta conectada neste navegador.':'Cadastre a Redirect URI exatamente no painel do Spotify antes de conectar.'}</div></section></div>`}
function backgroundsAdmin(){const b=state.backgrounds||{};return `<section class="background-admin"><div class="section-kicker">APARÊNCIA DA PROFECIA</div><h2>Planos de fundo</h2><p class="small muted">O Mestre pode trocar cada fundo separadamente. As imagens ficam no IndexedDB deste navegador para não sobrecarregar o LocalStorage. O fundo original volta automaticamente se uma imagem for removida.</p><div class="background-grid">${Object.entries(BG_DEFS).map(([k,d])=>{const cfg=b[k]||{};return `<article class="background-card"><div class="background-preview" data-bg-preview="${k}" style="background-image:linear-gradient(90deg,rgba(0,0,0,.45),rgba(0,0,0,.15)),url('${esc(cfg.preview||d[1])}')"><span>${esc(d[0])}</span></div><div class="background-meta"><strong>${esc(d[0])}</strong><small>Original: ${esc(d[1])}</small><input type="file" accept="image/png,image/jpeg,image/webp,image/avif" data-bg-upload="${k}"><div class="row"><button class="btn small primary" data-bg-save="${k}">Aplicar</button><button class="btn small danger" data-bg-clear="${k}">Restaurar original</button></div></div></article>`}).join('')}</div></section>`}
function bindBackgrounds(){Object.keys(BG_DEFS).forEach(kind=>{const cfg=state.backgrounds?.[kind];if(!cfg?.mediaId)return;bgGet(cfg.mediaId).then(blob=>{if(!blob)return;const u=URL.createObjectURL(blob),preview=document.querySelector(`[data-bg-preview=\"${kind}\"]`);if(preview){preview.style.backgroundImage=`linear-gradient(90deg,rgba(0,0,0,.45),rgba(0,0,0,.15)),url(\"${u}\")`;}else URL.revokeObjectURL(u)}).catch(()=>{})});document.querySelectorAll('[data-bg-upload]').forEach(inp=>inp.onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Escolha uma imagem válida.');inp.value='';return}if(f.size>10*1024*1024){toast('A imagem deve ter até 10 MB.');inp.value='';return}const kind=inp.dataset.bgUpload;const card=inp.closest('.background-card'),preview=card?.querySelector('[data-bg-preview]');if(preview){if(preview.dataset.objectUrl)URL.revokeObjectURL(preview.dataset.objectUrl);const u=URL.createObjectURL(f);preview.dataset.objectUrl=u;preview.style.backgroundImage=`linear-gradient(90deg,rgba(0,0,0,.45),rgba(0,0,0,.15)),url(\"${u}\")`;}inp.dataset.ready='1';});document.querySelectorAll('[data-bg-save]').forEach(btn=>btn.onclick=async()=>{const kind=btn.dataset.bgSave,input=document.querySelector(`[data-bg-upload="${kind}"]`),file=input?.files?.[0];if(!file){toast('Escolha uma imagem antes de aplicar.');return}try{const id=`bg-${kind}-${Date.now()}`;await bgPut(id,file);const old=state.backgrounds?.[kind]?.mediaId;if(old&&old!==id)await bgDelete(old).catch(()=>{});state.backgrounds=state.backgrounds||{};state.backgrounds[kind]={mediaId:id,name:file.name,updatedAt:Date.now()};save();await applyBackgrounds();toast(`${BG_DEFS[kind][0]} atualizado.`);document.getElementById('adminContent').innerHTML=backgroundsAdmin();bindBackgrounds()}catch(e){toast('Não foi possível salvar este fundo.');}});document.querySelectorAll('[data-bg-clear]').forEach(btn=>btn.onclick=async()=>{const kind=btn.dataset.bgClear;if(state.backgrounds?.[kind]?.mediaId)await bgDelete(state.backgrounds[kind].mediaId).catch(()=>{});if(state.backgrounds)delete state.backgrounds[kind];save();await applyBackgrounds();toast(`${BG_DEFS[kind][0]} restaurado.`);document.getElementById('adminContent').innerHTML=backgroundsAdmin();bindBackgrounds()});}
function classesAdmin(){return `<div class="card"><div class="row space"><div><h2>Classes</h2><p class="small muted">Consulta das classes disponíveis e seus bônus. A escolha do Player continua definitiva.</p></div></div><div class="class-book-grid admin-class-grid">${Object.entries(CLASSES).map(([n,c])=>`<article class="class-book-card"><div class="class-card-ornament">◇</div><div class="class-card-head"><h2>${esc(n)}</h2>${hasMagicClass(n)?'<span class="badge">MAGIA / RITUAL</span>':''}</div><p>${esc(c.desc)}</p><div class="class-bonus-line"><strong>Bônus</strong><span>${esc(c.bonus)}</span></div><div class="ability-list">${(c.abilities||[]).map(a=>`<div class="ability"><b>${esc(a[0])}</b><div class="small muted">${esc(a[1])}</div></div>`).join('')}</div></article>`).join('')}</div></div>`}

function bindAdmin(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const t=b.dataset.tab;const content=t==='players'?playersAdmin():t==='monsters'?monstersAdmin():t==='classes'?classesAdmin():t==='items'?itemsAdmin():t==='sounds'?soundsAdmin():t==='symbols'?symbolsAdmin():t==='spells'?spellsAdmin():t==='backgrounds'?backgroundsAdmin():musicAdmin();document.getElementById('adminContent').innerHTML=content;bindAdminContent()});bindAdminContent()}
function bindAdminContent(){const np=document.getElementById('newPlayer');if(np)np.onclick=()=>openEntity('player',null);document.querySelectorAll('[data-edit-p]').forEach(b=>b.onclick=()=>openEntity('player',Number(b.dataset.editP)));document.querySelectorAll('[data-bag-p]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.bagP);openModal(bagAdminModal(i));bindBagAdmin(i)});document.querySelectorAll('[data-round-p]').forEach(b=>b.onclick=()=>{const p=state.players[Number(b.dataset.roundP)];if(!p)return;const events=applyConditionRound(p);save();toast(events.length?events.join(' • '):'Rodada avançada. Nenhum efeito automático ativo.');render('master')});document.querySelectorAll('[data-del-p]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.delP);if(confirm('Excluir este Player?')){state.players.splice(i,1);save();render('master')}});const nm=document.getElementById('newMonster');if(nm)nm.onclick=()=>openEntity('monster',null);document.querySelectorAll('[data-edit-m]').forEach(b=>b.onclick=()=>openEntity('monster',Number(b.dataset.editM)));document.querySelectorAll('[data-round-m]').forEach(b=>b.onclick=()=>{const m=state.creatures[Number(b.dataset.roundM)];if(!m)return;const events=applyConditionRound(m);save();toast(events.length?events.join(' • '):'Rodada avançada. Nenhum efeito automático ativo.');render('master')});document.querySelectorAll('[data-del-m]').forEach(b=>b.onclick=()=>{if(confirm('Excluir este Monstro?')){state.creatures.splice(Number(b.dataset.delM),1);save();render('master')}});const ni=document.getElementById('newItem');if(ni)ni.onclick=()=>{openModal(itemModal());bindItemModal(null)};['itemSearch','itemCat','itemRar'].forEach(id=>{const x=document.getElementById(id);if(x)x.oninput=renderItems});const ci=document.getElementById('clearItems');if(ci)ci.onclick=()=>{document.getElementById('itemSearch').value='';document.getElementById('itemCat').value='';document.getElementById('itemRar').value='';renderItems()};document.querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>{openModal(itemModal(Number(b.dataset.editItem)));bindItemModal(Number(b.dataset.editItem))});document.querySelectorAll('[data-del-item]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.delItem);if(confirm('Excluir este item?')){state.items=state.items.filter(i=>i.id!==id);save();render('master')}});const sm=document.getElementById('saveMusic');if(sm)sm.onclick=async()=>{const type=document.getElementById('musicType').value,title=document.getElementById('musicTitle').value.trim();if(type==='spotify'){const url=document.getElementById('musicUrl')?.value.trim()||'';if(!spotifyResource(url)){toast('Link/URI do Spotify inválido.');return}if(state.music?.mediaId)await idbDeleteMusic(state.music.mediaId).catch(()=>{});state.music={type:'spotify',url,title,kind:'url',mediaId:''};save();syncGlobalMusic();toast('Trilha Spotify salva.');render('master');return}const file=document.getElementById('musicFile')?.files?.[0],url=document.getElementById('musicUrl')?.value.trim()||'';if(!file&&!url&&!state.music?.mediaId){toast('Escolha um arquivo ou informe uma URL direta.');return}if(file){if(!file.type.startsWith('audio/')){toast('O arquivo selecionado não é um áudio.');return}if(file.size>25*1024*1024){toast('O arquivo deve ter até 25 MB.');return}if(state.music?.mediaId)await idbDeleteMusic(state.music.mediaId).catch(()=>{});const mediaId='m-'+Date.now();await idbPutMusic(mediaId,file);state.music={type:'audio',url:'',title:title||file.name,kind:'file',mediaId};}else if(url){if(state.music?.mediaId)await idbDeleteMusic(state.music.mediaId).catch(()=>{});state.music={type:'audio',url,title,kind:'url',mediaId:''};}else{state.music={...state.music,type:'audio',title:title||state.music?.title||'Trilha local'};}save();syncGlobalMusic();toast('Trilha global salva.');render('master')};const scid=document.getElementById('spotifyClientId');if(scid)scid.onchange=()=>{try{localStorage.setItem(SPOTIFY_CLIENT_KEY,scid.value.trim())}catch{}};const slog=document.getElementById('spotifyLogin');if(slog)slog.onclick=async()=>{try{if(scid?.value.trim())localStorage.setItem(SPOTIFY_CLIENT_KEY,scid.value.trim())}catch{};if(spotifyLogged()){await ensureSpotifyPlayer();syncGlobalMusic()}else await spotifyLogin()};const slout=document.getElementById('spotifyLogout');if(slout)slout.onclick=()=>{spotifyLogout();render('master')};const cm=document.getElementById('clearMusic');if(cm)cm.onclick=async()=>{if(state.music?.mediaId)await idbDeleteMusic(state.music.mediaId).catch(()=>{});state.music={type:'',url:'',title:'',kind:'url',mediaId:''};save();syncGlobalMusic();toast('Trilha removida.');render('master')};const as=document.getElementById('addSound');if(as)as.onclick=async()=>{const name=document.getElementById('soundName').value.trim(),file=document.getElementById('soundFile').files[0],url=document.getElementById('soundUrl').value.trim();if(!name){toast('Informe o nome do som.');return}if(!file&&!url){toast('Envie um arquivo ou informe uma URL.');return}if(file&&file.size>8*1024*1024){toast('O arquivo deve ter até 8 MB.');return}const id='s-'+Date.now();if(file)await idbPutSound(id,file);state.sounds.push({id,name,kind:file?'file':'url',url:file?'':url});save();toast('Som guardado.');render('master')};document.querySelectorAll('[data-play-sound]').forEach(b=>b.onclick=()=>{const s=state.sounds.find(x=>x.id===b.dataset.playSound);if(!s)return;if(s.kind==='file')playStoredSound(s.id);else{const a=new Audio(s.url);a.play().catch(()=>toast('O navegador bloqueou o áudio; toque novamente.'))}});document.querySelectorAll('[data-del-sound]').forEach(b=>b.onclick=async()=>{const id=b.dataset.delSound;state.sounds=state.sounds.filter(x=>x.id!==id);await idbDeleteSound(id).catch(()=>{});save();render('master')});document.querySelectorAll('[data-class-choice]').forEach(b=>b.onclick=()=>{const p=player();if(!p)return;p.class=b.dataset.classChoice;if(!hasMagicClass(p.class))p.initialSpell='';save();const phrase=document.getElementById('destinyPhrase');if(phrase){phrase.classList.remove('show');void phrase.offsetWidth;phrase.classList.add('show')}toast('Seu destino está selado.');render('sheet')});const saveSymbols=document.getElementById('saveSymbols');if(saveSymbols)saveSymbols.onclick=()=>{state.uiIcons=state.uiIcons||{attrs:{},skills:{},conditions:{}};state.uiIcons.attrs=state.uiIcons.attrs||{};state.uiIcons.skills=state.uiIcons.skills||{};document.querySelectorAll('[data-symbol-attr]').forEach(x=>state.uiIcons.attrs[x.dataset.symbolAttr]=x.value.trim()||DEFAULT_ATTR_ICONS[x.dataset.symbolAttr]);document.querySelectorAll('[data-symbol-skill]').forEach(x=>state.uiIcons.skills[x.dataset.symbolSkill]=x.value.trim()||DEFAULT_SKILL_ICONS[x.dataset.symbolSkill]);save();toast('Símbolos atualizados.');render('master')};document.querySelectorAll('[data-symbol-file]').forEach(inp=>inp.onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const data=await imageFileToDataURL(f,128,.8);state.uiIcons=state.uiIcons||{attrs:{},skills:{},conditions:{}};const kind=inp.dataset.symbolFile,key=inp.dataset.symbolKey;if(kind==='attr')state.uiIcons.attrs[key]=data;else state.uiIcons.skills[key]=data;save();toast('Ícone atualizado.');document.getElementById('adminContent').innerHTML=symbolsAdmin();bindAdminContent()}catch(err){toast('Não foi possível preparar essa imagem.')}finally{inp.value=''}});document.querySelectorAll('[data-spell-image]').forEach(inp=>inp.onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast('Imagem inválida ou maior que 5 MB.');return}const r=new FileReader();r.onload=()=>{const sp=state.spells.find(x=>x.id===inp.dataset.spellImage);if(sp){sp.image=r.result;save();render('master')}};r.readAsDataURL(f)});document.querySelectorAll('[data-clear-spell-image]').forEach(b=>b.onclick=()=>{const sp=state.spells.find(x=>x.id===b.dataset.clearSpellImage);if(sp){sp.image='';save();render('master')}});document.querySelectorAll('[data-condition-image]').forEach(inp=>inp.onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast('Imagem inválida ou maior que 5 MB.');return}const r=new FileReader();r.onload=()=>{state.uiIcons=state.uiIcons||{};state.uiIcons.conditions=state.uiIcons.conditions||{};state.uiIcons.conditions[inp.dataset.conditionImage]=r.result;save();render('master')};r.readAsDataURL(f)});if(document.getElementById('itemResults'))renderItems();if(document.querySelector('[data-bg-upload]'))bindBackgrounds()}
function openModal(html){const holder=document.createElement('div');holder.innerHTML=html.trim();document.body.appendChild(holder.firstElementChild)}
function login(){document.getElementById('root').innerHTML=`<div class="screen"><form class="login-card" id="loginForm"><img class="sigil" src="runa-gold.png"><h1 class="title">A Profecia</h1><p class="welcome">Bem-vindos ao abismo</p><p class="subtitle">Entre para continuar sua jornada.</p><div class="field"><label>Login</label><input id="login" autocomplete="username" required></div><div class="field"><label>Senha</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn primary full">Entrar</button></form></div>`;document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const l=document.getElementById('login').value.trim(),p=document.getElementById('password').value;if(l===MASTER.login&&p===MASTER.password){state.session={role:'master'};save();render('home');return}if(state.players.some(x=>x.login===l&&x.password===p)){state.session={role:'player',login:l};save();render('home');return}toast('Credenciais inválidas.')}}
function entityModal(type,index){const isP=type==='player',e=index===null?{id:'',name:'',login:'',password:'',class:'',status:'Ativo',hp:1,hpMax:1,sanity:1,sanityMax:1,attack:0,defense:0,extra:0,attrs:blankAttrs(),attrLimits:blankLimits(),skills:blankSkills(),backpack:[],conditions:[],conditionTurns:{},description:'',history:'',soul:'',belovedObjects:'',personality:'',destiny:'',initialSpell:''}:clone((isP?state.players:state.creatures)[index]);const attrRows=ATTRS.map(a=>`<label class="skill-line"><span class="skill-name"><i class="skill-icon">${uiAttrIcon(a)}</i>${esc(a)}</span><input class="eAttr" data-attr="${esc(a)}" type="number" min="0" max="8" value="${e.attrs?.[a]??0}"><b>/8</b></label>`).join('');const skillRows=SKILLS.map(sk=>`<label class="skill-line"><span class="skill-name"><i class="skill-icon">${uiSkillIcon(sk)}</i>${esc(sk)}</span><input class="eSkill" data-skill="${esc(sk)}" type="number" min="0" max="15" value="${e.skills?.[sk]??0}"><b>/15</b></label>`).join('');return `<div class="modal" id="entityModal"><div class="modal-card"><button class="modal-close" id="closeEntity">×</button><span class="badge">MESTRE</span><h2>${index===null?'Criar':'Editar'} ${isP?'Player':'Monstro'}</h2><div class="input-grid"><div class="field"><label>Nome</label><input id="eName" value="${esc(e.name||'')}"></div>${isP?`<div class="field"><label>Login</label><input id="eLogin" value="${esc(e.login||'')}"></div><div class="field"><label>Senha</label><input id="ePass" type="password" value="${esc(e.password||'')}"></div><div class="field"><label>Classe</label><select id="eClass"><option value="">Escolher depois pelo Player</option>${Object.keys(CLASSES).map(c=>`<option ${e.class===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Status</label><input id="eStatus" value="${esc(e.status||'Ativo')}"></div><div class="field"><label>Vida atual</label><input id="hpMax" type="number" min="1" max="35" value="${Math.min(35,e.hpMax||1)}"></div><div class="field"><label>Vida</label><input id="hp" type="number" min="0" max="35" value="${Math.min(35,e.hp??1)}"></div><div class="field"><label>Ataque</label><input id="attack" type="number" value="${e.attack||0}"></div><div class="field"><label>Defesa</label><input id="defense" type="number" value="${e.defense||0}"></div>${isP?`<div class="field"><label>Pontos extras</label><input id="eExtra" type="number" min="0" value="${e.extra||0}"></div>`:''}</div>${isP?`<div class="field"><label>Descrição</label><textarea id="eDescription" rows="3">${esc(e.description||'')}</textarea></div><div class="field"><label>História</label><textarea id="eHistory" rows="3">${esc(e.history||'')}</textarea></div><div class="input-grid"><div class="field"><label>Alma</label><input id="eSoul" value="${esc(e.soul||'')}"></div><div class="field"><label>Objetos queridos</label><input id="eBeloved" value="${esc(e.belovedObjects||'')}"></div><div class="field"><label>Personalidade</label><input id="ePersonality" value="${esc(e.personality||'')}"></div><div class="field"><label>Destino</label><input id="eDestiny" value="${esc(e.destiny||'')}"></div></div>`:''}<div class="divider"></div><div class="section-heading"><div><span class="section-kicker">ATRIBUTOS</span><h3>Pontos do personagem</h3></div><span class="corner-mark">máx. 8</span></div><div class="attribute-admin-grid">${attrRows}</div><div class="section-heading" style="margin-top:18px"><div><span class="section-kicker">PERÍCIAS</span><h3>Distribuição</h3></div><span class="corner-mark">máx. 15</span></div><div class="skill-admin-grid">${skillRows}</div><div class="section-heading" style="margin-top:18px"><div><span class="section-kicker">ESTADOS</span><h3>Condições</h3></div></div>${conditionsMarkup(e,true)}<div class="row" style="justify-content:flex-end;margin-top:18px"><button class="btn" id="cancelEntity">Cancelar</button><button class="btn primary" id="saveEntity">Salvar</button></div></div></div>`}
function openEntity(type,index){openModal(entityModal(type,index));bindEntity(type,index)}
function bindEntity(type,index){const close=()=>document.getElementById('entityModal')?.remove();document.getElementById('closeEntity').onclick=close;document.getElementById('cancelEntity').onclick=close;document.querySelectorAll('#entityModal .condition-chip').forEach(b=>b.onclick=()=>b.classList.toggle('active'));document.getElementById('saveEntity').onclick=()=>{const isP=type==='player',list=isP?state.players:state.creatures;let e=index===null?{id:'e-'+Date.now(),name:'',login:'',password:'',class:'Guerreiro',hp:10,hpMax:10,attack:0,defense:0,status:'Ativo',attrs:blankAttrs(),attrLimits:blankLimits(),skills:blankSkills(),backpack:[],conditions:[],conditionTurns:{},rolls:[],history:'',initialSpell:''}:list[index];e.name=document.getElementById('eName').value.trim();if(!e.name){toast('Informe um nome.');return}e.status=document.getElementById('eStatus').value.trim()||'Ativo';if(isP){e.description=document.getElementById('eDescription')?.value.trim()||'';e.extra=Math.max(0,Number(document.getElementById('eExtra')?.value)||0)}const previousConditions=new Set(e.conditions||[]);const nextConditions=[...document.querySelectorAll('#entityModal .condition-chip.active')].map(x=>x.dataset.condition);e.conditionTurns=e.conditionTurns||{};for(const id of Object.keys(e.conditionTurns)){if(!nextConditions.includes(id))delete e.conditionTurns[id]}e.conditions=nextConditions;for(const id of nextConditions){const c=conditionById(id);if(c?.turns&&!previousConditions.has(id))e.conditionTurns[id]=c.turns}if(isP)e.history=document.getElementById('eHistory')?.value.trim()||e.history||'';if(isP){e.soul=document.getElementById('eSoul')?.value.trim()||'';e.belovedObjects=document.getElementById('eBeloved')?.value.trim()||'';e.personality=document.getElementById('ePersonality')?.value.trim()||'';e.destiny=document.getElementById('eDestiny')?.value.trim()||'';}e.hpMax=clamp(document.getElementById('hpMax').value,1,MAX_HP);e.hp=clamp(document.getElementById('hp').value,0,e.hpMax);e.attack=Number(document.getElementById('attack').value)||0;e.defense=Number(document.getElementById('defense').value)||0;if(isP){e.login=document.getElementById('eLogin').value.trim();e.password=document.getElementById('ePass').value;e.class=document.getElementById('eClass').value;e.initialSpell=e.initialSpell||'';if(!hasMagicClass(e.class))e.initialSpell='';if(!e.login||!e.password){toast('Login e senha são obrigatórios.');return}if(e.login===MASTER.login||state.players.some((p,i)=>i!==index&&p.login===e.login)){toast('Esse login já existe.');return}}e.attrLimits=e.attrLimits||blankLimits();e.attrs=e.attrs||blankAttrs();document.querySelectorAll('.eMin').forEach(x=>e.attrLimits[x.dataset.attr].min=Number(x.value)||0);document.querySelectorAll('.eMax').forEach(x=>e.attrLimits[x.dataset.attr].max=Number(x.value)||10);document.querySelectorAll('.eAttr').forEach(x=>{const l=e.attrLimits[x.dataset.attr];e.attrs[x.dataset.attr]=clamp(x.value,0,MAX_ATTR)});e.skills=e.skills||blankSkills();document.querySelectorAll('.eSkill').forEach(x=>e.skills[x.dataset.skill]=clamp(x.value,0,MAX_SKILL));if(isP)syncDerivedResources(e);normalize(e);if(index===null)list.push(e);save();close();toast(`${isP?'Player':'Monstro'} salvo.`);render('master')}}
function bindItemModal(id){const close=()=>document.getElementById('itemModal')?.remove();document.getElementById('closeItem').onclick=close;document.getElementById('cancelItem').onclick=close;document.getElementById('saveItem').onclick=()=>{let n=Number(document.getElementById('iId').value);if(!Number.isInteger(n)||n<1){toast('ID inválido.');return}if(id===null&&state.items.some(i=>i.id===n)){toast('Já existe um item com esse ID.');return}if(id===300)n=300;const e=id===null?{id:n}:item(id);e.id=n;if(n===300){e.name='Chave';e.category='Itens Chave';e.description=e.description||'Uma chave simples para uma fechadura compatível.';e.icon='asset:key';e.weight=1}e.name=document.getElementById('iName').value.trim();e.description=document.getElementById('iDesc').value.trim();e.category=document.getElementById('iCat').value;e.maxQty=Math.max(1,Number(document.getElementById('iMax').value)||1);e.weight=clamp(document.getElementById('iWeight').value,1,3);e.icon=document.getElementById('iIcon').value.trim()||'✦';e.effects=document.getElementById('iEffects').value.trim();e.rarity=document.getElementById('iRar').value;if(!e.name){toast('Informe o nome do item.');return}if(id===null)state.items.push(e);save();close();toast('Item salvo.');render('master')}}
function render(view='home'){const validSession=state.session?.role==='master'||(state.session?.role==='player'&&!!state.session.login&&state.players.some(p=>p.login===state.session.login));if(!validSession){state.session=null;login();syncSoundboard();return}let html=view==='sheet'?(state.session.role==='master'?masterFicha():sheet()):view==='classes'?classesPage():view==='master'&&state.session.role==='master'?admin():home();document.getElementById('root').innerHTML=html;bindNav();if(view==='home'){document.getElementById('spotifyHomePlay')?.addEventListener('click',spotifyPlayCurrent);document.getElementById('spotifyHomePause')?.addEventListener('click',spotifyPause);document.getElementById('spotifyHomeLogin')?.addEventListener('click',async()=>{let id=spotifyClientId();if(!id){id=prompt('Cole o Client ID do seu aplicativo Spotify:')?.trim()||'';if(id)try{localStorage.setItem(SPOTIFY_CLIENT_KEY,id)}catch{}}if(id)await spotifyLogin()})}if(view==='master')bindAdmin();if(view==='sheet'&&state.session.role==='master')bindMasterFicha();if(view==='sheet'&&state.session.role==='player')bindSheet();if(view==='classes'){const choose=b=>{const p=player();if(!p||classChosen(p)){toast('A classe já foi escolhida e não pode ser alterada.');return}const name=b.dataset.classChoice;if(!confirm(`Escolher ${name}?\n\nEsta escolha é definitiva para este personagem.`))return;p.class=name;p.initialSpell='';save();toast('Seu destino está selado.');render('sheet')};document.querySelectorAll('[data-class-choice]').forEach(b=>{b.setAttribute('role','button');b.setAttribute('tabindex','0');b.onclick=()=>choose(b);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(b)}}})}syncGlobalMusic();syncSoundboard();applyBackgrounds()}
handleSpotifyCallback().finally(async()=>{if(spotifyLogged())await ensureSpotifyPlayer();render();syncGlobalMusic();syncSoundboard();applyBackgrounds();angelEnsure()});
